    # Use each unique letter from the input as a key
    for letter in set(LETTERS):
        # Generate a list of random integers for each key (at least 1 to avoid statistics.mean error on empty lists)
        d[letter] = [random.randint(-100, 100) for _ in range(random.randint(1, 20))]

    # Sort the dictionary by the mean of the integer lists in descending order
    sorted_d = dict(sorted(d.items(), key=lambda item: statistics.mean(item[1]), reverse=True))

